{"path": "textutils.py", "content": "import re
from collections import Counter

_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map lower-cased words to their counts.

    Words are runs of letters, digits and apostrophes; everything else
    (punctuation, whitespace, underscores) separates words.
    """
    return dict(Counter(_WORD_RE.findall(text.lower())))
"}

